describe('punycodeUrl', function () {
    it('should encode an internationalized hostname without adding a trailing slash', () => {
        expect(punycodeUrl('https://www.аррӏе.com')).toEqual('https://www.xn--80ak6aa92e.com');
    });

    it('should preserve the protocol, port, path, query, and fragment while removing a trailing path slash', () => {
        const url = 'http://www.аррӏе.com:8443/path/to/resource/?next=https%3A%2F%2Fexample.com%2Fpage&item=1#section';

        expect(punycodeUrl(url)).toEqual(
            'http://www.xn--80ak6aa92e.com:8443/path/to/resource?next=https%3A%2F%2Fexample.com%2Fpage&item=1#section'
        );
    });

    it('should leave Unicode in the path, query, and fragment with the same meaning', () => {
        const converted = new URL(punycodeUrl('https://www.аррӏе.com/café?next=https://bücher.example/über#résumé'));

        expect(converted.hostname).toEqual('www.xn--80ak6aa92e.com');
        expect(decodeURIComponent(converted.pathname)).toEqual('/café');
        expect(converted.searchParams.get('next')).toEqual('https://bücher.example/über');
        expect(decodeURIComponent(converted.hash)).toEqual('#résumé');
    });
});

