import { ReactNode, RefObject, useEffect, useState } from 'react';

import { c } from 'ttag';

import { PROTON_DOMAINS } from '@proton/shared/lib/constants';
import { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';
import { MailSettings } from '@proton/shared/lib/interfaces';
import isTruthy from '@proton/utils/isTruthy';

import { useModalState } from '../components';
import LinkConfirmationModal from '../components/notifications/LinkConfirmationModal';
import { getHostname, isExternal, isSubDomain, punycodeUrl } from '../helpers/url';
import { useHandler, useNotifications } from './index';

// Reference : Angular/src/app/utils/directives/linkHandler.js

interface LinkSource {
    raw: string;
}

interface UseLinkHandlerOptions {
    onMailTo?: (src: string) => void;
    startListening?: boolean;
    isOutside?: boolean;
    isPhishingAttempt?: boolean;
}
type UseLinkHandler = (
    wrapperRef: RefObject<HTMLDivElement | undefined>,
    mailSettings?: MailSettings,
    options?: UseLinkHandlerOptions
) => { modal: ReactNode };

const defaultOptions: UseLinkHandlerOptions = {
    startListening: true,
};
export const useLinkHandler: UseLinkHandler = (
    wrapperRef,
    mailSettings,
    { onMailTo, startListening, isOutside, isPhishingAttempt } = defaultOptions
) => {
    const { createNotification } = useNotifications();
    const [link, setLink] = useState<string>();

    const [linkConfirmationModalProps, setLinkConfirmationModalOpen] = useModalState();

    const notifyInvalidLink = () => {
        createNotification({
            text: c('Error').t`This message may contain some link's URL that cannot be properly opened by your current browser.`,
            type: 'error',
        });
    };

    const getSrc = (target: Element): LinkSource => {
        const extract = () => {
            try {
                return { raw: target.getAttribute('href') || '' };
            } catch (e: any) {
                /*
                    Because for Edge/IE11
                    <a href="http://xn--rotonmail-4sg.com" rel="noreferrer nofollow noopener">Protonmail.com</a>
                    will crash --> Unspecified error. ¯\_(ツ)_/¯
                    Don't worry, target.href/getAttribute will crash too ¯\_(ツ)_/¯
                    Ivre, ...
                 */
                const attr = Array.from(target.attributes).find((attr) => (attr || {}).name === 'href');
                return { raw: attr?.nodeValue || '' };
            }
        };

        // Because even the fallback canq crash on IE11/Edge. (Now it's a matter of random env issue...)
        try {
            return extract();
        } catch (e: any) {
            return { raw: '' };
        }
    };

    const handleClick = useHandler((event: Event) => {
        const originalTarget = event.target as Element;
        const target = originalTarget.closest('a');

        if (!target) {
            return;
        }

        const src = getSrc(target);

        if (!src.raw) {
            event.preventDefault();
            event.stopPropagation();
            notifyInvalidLink();
            return false;
        }

        // We only handle anchor that begins with `mailto:`
        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            /*
             * Open the composer with the given mailto address
             * position isAfter true as the user can choose to set a body
             */
            onMailTo(src.raw);
        }

        /*
         * If the modal is already active --- do nothing
         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.
         */
        if (linkConfirmationModalProps.open) {
            return;
        }

        /*
         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements
         */
        if (src.raw.startsWith('#')) {
            const id = src.raw.replace('#', '');
            if (wrapperRef.current) {
                const elementInMail = wrapperRef.current.querySelector(`a[name="${id}"], a[id="${id}"]`);
                if (elementInMail) {
                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        const external = isExternal(src.raw);
        let url = src.raw;

        if (external) {
            try {
                url = punycodeUrl(src.raw);
            } catch (e: any) {
                event.preventDefault();
                event.stopPropagation();
                notifyInvalidLink();
                return false;
            }
        }

        const askForConfirmation = mailSettings?.ConfirmLink === undefined ? 1 : mailSettings?.ConfirmLink;
        const hostname = getHostname(url);
        const currentDomain = getSecondLevelDomain(window.location.hostname);

        const shouldConfirm =
            (askForConfirmation || isPhishingAttempt) &&
            external &&
            ![...PROTON_DOMAINS, currentDomain]
                .filter(isTruthy) // currentDomain can be null
                .some((domain) => isSubDomain(hostname, domain));

        if (shouldConfirm) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            setLink(url);

            setLinkConfirmationModalOpen(true);
        } else if (external && url !== src.raw) {
            try {
                target.setAttribute('href', url);
            } catch (e: any) {
                event.preventDefault();
                event.stopPropagation();
                notifyInvalidLink();
                return false;
            }
        }
    });

    useEffect(() => {
        if (startListening === false) {
            return;
        }

        wrapperRef.current?.addEventListener('click', handleClick, false);
        return () => {
            wrapperRef.current?.removeEventListener('click', handleClick, false);
        };
    }, [startListening, wrapperRef.current]);

    const modal = (
        <LinkConfirmationModal
            link={link}
            isOutside={isOutside}
            isPhishingAttempt={isPhishingAttempt}
            {...linkConfirmationModalProps}
        />
    );

    return { modal };
};

import { useState } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { updateConfirmLink } from '@proton/shared/lib/api/mailSettings';
import { isEdge, isIE11, openNewTab } from '@proton/shared/lib/helpers/browser';
import { rtlSanitize } from '@proton/shared/lib/helpers/string';
import { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';

import { useApi, useEventManager } from '../../hooks';
import { Form } from '../form';
import { Checkbox } from '../input';
import { Label } from '../label';
import { Href } from '../link';
import { ModalProps, ModalTwo, ModalTwoContent, ModalTwoFooter, ModalTwoHeader } from '../modalTwo';

interface Props extends ModalProps {
    link?: string;
    isOutside?: boolean;
    isPhishingAttempt?: boolean;
}

const LinkConfirmationModal = ({ link = '', isOutside = false, isPhishingAttempt = false, ...rest }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [dontAskAgain, setDontAskAgain] = useState(false);
    const [understandRisk, setUnderstandRisk] = useState(false);

    const { onClose } = rest;

    // https://jira.protontech.ch/browse/SEC-574
    const linkToShow = rtlSanitize(link);

    // Both are not able to open the link
    const punyCodeLink = /:\/\/xn--/.test(link);

    const punyCodeLinkText =
        isEdge() || isIE11()
            ? c('Info')
                  .t`This link may be a homograph attack and cannot be opened by Edge browsers. If you are certain the link is legitimate, please use a different browser to open it.`
            : c('Info')
                  .t`This link may be a homograph attack. Please verify this is the link you wish to visit, or don't open it.`;

    const handleConfirm = async () => {
        openNewTab(link);

        if (dontAskAgain && !isOutside) {
            await api(updateConfirmLink(0));
            await call();
        }

        onClose?.();
    };

    const content = isPhishingAttempt ? (
        <>
            {`${c('Info')
                .t`This link leads to a website that might be trying to steal your information, such as passwords and credit card details.`} `}
            <br />
            <span className="text-bold text-break">{linkToShow}</span>

            <Label className="flex">
                <Checkbox
                    className="mr0-5"
                    checked={understandRisk}
                    onChange={() => setUnderstandRisk(!understandRisk)}
                />
                {c('Label').t`I understand the risk`}
            </Label>
        </>
    ) : (
        <>
            {`${c('Info').t`You are about to open another browser tab and visit:`} `}
            <span className="text-bold text-break">{linkToShow}</span>

            {punyCodeLink && (
                <>
                    {`${punyCodeLinkText} `}
                    <Href url={getKnowledgeBaseUrl('/homograph-attacks')} title="What are homograph attacks?">
                        {c('Info').t`Learn more`}
                    </Href>
                </>
            )}

            {!isOutside && (
                <Label className="flex">
                    <Checkbox
                        checked={dontAskAgain}
                        onChange={() => setDontAskAgain(!dontAskAgain)}
                        className="mr0-5"
                    />
                    {c('Label').t`Do not ask again`}
                </Label>
            )}
        </>
    );

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleConfirm} {...rest}>
            <ModalTwoHeader
                title={
                    isPhishingAttempt ? c('Title').t`Warning: suspected fake website` : c('Title').t`Link confirmation`
                }
            />
            <ModalTwoContent>{content}</ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                {/* translator: this string is only for blind people, it will be vocalized: confirm opening of link https://link.com */}
                <Button
                    color="norm"
                    type="submit"
                    autoFocus
                    aria-label={c('Action').t`Confirm opening of link ${linkToShow}`}
                    disabled={isPhishingAttempt && !understandRisk}
                >
                    {c('Action').t`Confirm`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
};

export default LinkConfirmationModal;

import { useRef } from 'react';

import { fireEvent, render, screen } from '@testing-library/react';

import { MailSettings } from '@proton/shared/lib/interfaces';

import { useLinkHandler } from './useLinkHandler';

const mockCreateNotification = jest.fn();

jest.mock('../components', () => ({
    useModalState: () => {
        const [open, setOpen] = jest.requireActual('react').useState(false);
        return [{ open }, setOpen];
    },
}));

jest.mock('../components/notifications/LinkConfirmationModal', () => ({
    __esModule: true,
    default: ({ link, open }: { link?: string; open: boolean }) =>
        jest.requireActual('react').createElement('div', { 'data-testid': 'link-confirmation', 'data-open': open }, link),
}));

jest.mock('./index', () => ({
    useHandler: (handler: (event: Event) => void) => handler,
    useNotifications: () => ({ createNotification: mockCreateNotification }),
}));

const TestLinkHandler = ({ href, confirmLink }: { href?: string; confirmLink?: number }) => {
    const wrapperRef = useRef<HTMLDivElement>(null);
    const { modal } = useLinkHandler(wrapperRef, { ConfirmLink: confirmLink } as MailSettings);

    return (
        <div ref={wrapperRef}>
            <a data-testid="link" href={href}>
                Link
            </a>
            {modal}
        </div>
    );
};

describe('useLinkHandler', () => {
    beforeEach(() => mockCreateNotification.mockClear());

    it('shows the punycode hostname in external link confirmation', () => {
        render(<TestLinkHandler href="https://www.аррӏе.com/path?next=https://example.com/#section" confirmLink={1} />);

        fireEvent.click(screen.getByTestId('link'));

        expect(screen.getByTestId('link-confirmation')).toHaveAttribute('data-open', 'true');
        expect(screen.getByTestId('link-confirmation')).toHaveTextContent(
            'https://www.xn--80ak6aa92e.com/path?next=https://example.com/#section'
        );
    });

    it('uses the punycode URL for direct external navigation', () => {
        render(<TestLinkHandler href="https://www.аррӏе.com/path?query=1#section" confirmLink={0} />);

        const link = screen.getByTestId('link');
        fireEvent.click(link);

        expect(link).toHaveAttribute('href', 'https://www.xn--80ak6aa92e.com/path?query=1#section');
        expect(screen.getByTestId('link-confirmation')).toHaveAttribute('data-open', 'false');
    });

    it('shows an error notification when an anchor has no URL', () => {
        render(<TestLinkHandler />);

        fireEvent.click(screen.getByTestId('link'));

        expect(mockCreateNotification).toHaveBeenCalledWith(
            expect.objectContaining({ type: 'error', text: expect.stringContaining('URL') })
        );
    });
});

