import { useRef } from 'react';

import { fireEvent, render, screen } from '@testing-library/react';

import { MailSettings } from '@proton/shared/lib/interfaces';

import { useLinkHandler } from './useLinkHandler';

const mockCreateNotification = jest.fn();

jest.mock('../components', () => ({
    useModalState: () => {
        const [open, setOpen] = jest.requireActual('react').useState(false);
        return [{ open }, setOpen];
    },
}));

jest.mock('../components/notifications/LinkConfirmationModal', () => ({
    __esModule: true,
    default: ({ link, open }: { link?: string; open: boolean }) =>
        jest.requireActual('react').createElement('div', { 'data-testid': 'link-confirmation', 'data-open': open }, link),
}));

jest.mock('./index', () => ({
    useHandler: (handler: (event: Event) => void) => handler,
    useNotifications: () => ({ createNotification: mockCreateNotification }),
}));

const TestLinkHandler = ({ href, confirmLink }: { href?: string; confirmLink?: number }) => {
    const wrapperRef = useRef<HTMLDivElement>(null);
    const { modal } = useLinkHandler(wrapperRef, { ConfirmLink: confirmLink } as MailSettings);

    return (
        <div ref={wrapperRef}>
            <a data-testid="link" href={href}>
                Link
            </a>
            {modal}
        </div>
    );
};

describe('useLinkHandler', () => {
    beforeEach(() => mockCreateNotification.mockClear());

    it('shows the punycode hostname in external link confirmation', () => {
        render(<TestLinkHandler href="https://www.аррӏе.com/path?next=https://example.com/#section" confirmLink={1} />);

        fireEvent.click(screen.getByTestId('link'));

        expect(screen.getByTestId('link-confirmation')).toHaveAttribute('data-open', 'true');
        expect(screen.getByTestId('link-confirmation')).toHaveTextContent(
            'https://www.xn--80ak6aa92e.com/path?next=https://example.com/#section'
        );
    });

    it('uses the punycode URL for direct external navigation', () => {
        render(<TestLinkHandler href="https://www.аррӏе.com/path?query=1#section" confirmLink={0} />);

        const link = screen.getByTestId('link');
        fireEvent.click(link);

        expect(link).toHaveAttribute('href', 'https://www.xn--80ak6aa92e.com/path?query=1#section');
        expect(screen.getByTestId('link-confirmation')).toHaveAttribute('data-open', 'false');
    });

    it('shows an error notification when an anchor has no URL', () => {
        render(<TestLinkHandler />);

        fireEvent.click(screen.getByTestId('link'));

        expect(mockCreateNotification).toHaveBeenCalledWith(
            expect.objectContaining({ type: 'error', text: expect.stringContaining('URL') })
        );
    });

    it('blocks an external link that cannot be parsed', () => {
        render(<TestLinkHandler href="https://[invalid" confirmLink={0} />);

        const link = screen.getByTestId('link');
        const clickWasAllowed = fireEvent.click(link);

        expect(clickWasAllowed).toBe(false);
        expect(mockCreateNotification).toHaveBeenCalledWith(expect.objectContaining({ type: 'error' }));
    });
});

import punycode from 'punycode.js';

import { getSecondLevelDomain } from '@proton/shared/lib/helpers/url';
import isTruthy from '@proton/utils/isTruthy';

export const isSubDomain = (hostname: string, domain: string) => {
    if (hostname === domain) {
        return true;
    }

    return hostname.endsWith(`.${domain}`);
};

export const getHostname = (url: string) => {
    // The easy way to parse an URL, is to create <a> element.
    // @see: https://gist.github.com/jlong/2428561
    const parser = document.createElement('a');
    parser.href = url;
    return parser.hostname;
};

/** Return the domain label immediately before the top-level domain. */
export const getHostnameWithRegex = (url: string): string => {
    const match =
        /^(?:(?:[a-z][a-z\d+.-]*:)?\/\/)?(?:[^/?#@]*@)?(?:[^./?#:]+\.)*?([^./?#:]+)\.[^./?#:]+(?::\d+)?(?:[/?#]|$)/i.exec(
            url
        );
    return match?.[1] || '';
};

/** Encode only the hostname, keeping the other URL components as supplied. */
export const punycodeUrl = (url: string): string => {
    // Keep the original path, query, and fragment: URL serialization can encode
    // their Unicode characters and change the text of a link.
    const parts = /^((?:[a-z][a-z\d+.-]*:)?\/\/)([^/?#\\]+)([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(url);
    if (!parts || url.includes('\\')) {
        throw new TypeError('Invalid URL');
    }

    const [, prefix, authority, pathname, search = '', hash = ''] = parts;
    const authorityParts = /^(.*@)?(\[[^\]]+\]|[^:]+)(:\d*)?$/.exec(authority);
    if (!authorityParts) {
        throw new TypeError('Invalid URL');
    }

    const parsed = new URL(url, 'https://example.invalid');
    if (!parsed.hostname) {
        throw new TypeError('Invalid URL');
    }

    const [, userInfo = '', , port = ''] = authorityParts;
    const hostname = punycode.toASCII(parsed.hostname);
    return `${prefix}${userInfo}${hostname}${port}${pathname.replace(/\/+$/, '')}${search}${hash}`;
};

export const isMailTo = (url: string): boolean => {
    return url.toLowerCase().startsWith('mailto:');
};

export const isExternal = (url: string) => {
    try {
        return window.location.hostname !== getHostname(url) && !isMailTo(url);
    } catch (e: any) {
        /*
         * IE11/Edge are the worst, they crash when they try to parse
         * ex: http://xn--rotonmail-4sg.com
         * so if it does we know it's an external link (⌐■_■)
         */
        return true;
    }
};

export const isURLProtonInternal = (url: string) => {
    const currentDomain = getSecondLevelDomain(window.location.hostname);
    const targetOriginHostname = getHostname(url);

    // Still need to check the current domain otherwise it would not work on proton.local, localhost, etc...
    return ['protonmail.com', currentDomain]
        .filter(isTruthy)
        .some((domain) => isSubDomain(targetOriginHostname, domain));
};

